function initGalleryVideoPlayers(panel){panel.querySelectorAll('.gallery-video-player').forEach(player=>{const video=player.querySelector('video'),button=player.querySelector('button');button.onclick=()=>{button.hidden=true;video.controls=true;video.play().catch(()=>{button.hidden=false;video.controls=false})};video.onplay=()=>{panel.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause()});button.hidden=true;video.controls=true}})}
const unarteVideoFiles=["00 Echipa 6 .mp4", "00 Mario .mp4", "Donare De Sange - Scena 1 .mp4", "Donare De Sange - Scena 2 .mp4", "Donare De Sange - Scena 3 .mp4", "Donează 02 .mp4", "Donează 03 .mp4", "Donează 04 .mp4", "Echipa 1 .mp4", "Echipa 3 .mp4", "Echipa 5 .mp4", "Echipa 7 .mp4", "Fdbs Animatie .mp4", "Passion Runs Though My Veins - Promovare Donare De Sange .mp4", "Sange 3 .mp4", "Video Donare Sange O Oră .mp4", "Videoclip Vampiri .mp4"];
const galleryVideoFiles={'UNArte':unarteVideoFiles,'Logo Bigger':['Doneaza Sange 30S Cinema Wav .mp4'],'Donorium':['campania-iesdoarsadonez.mp4']};
function renderGalleryVideos(category){const files=galleryVideoFiles[category]||[];if(!files.length)return `<b>${category}</b><br><span>Videoclipurile din această categorie vor fi adăugate aici.</span>`;return `${category==='UNArte'?'<p>Prin amabilitatea profesorului Iosif Oprescu, studenții de la <a href="https://unarte.org/">Universitatea Națională de Arte București</a> primesc în fiecare generație promovarea donării de sânge ca temă de exercițiu, prin video, postere, flyere și stickere. Unele dintre clipurile create de studenți sunt urcate aici, adesea cu logo-uri alternative create tot de ei.</p>':''}<div class="gallery-video-grid">${files.map(file=>{const title=file==='campania-iesdoarsadonez.mp4'?'Campania #iesdoarsadonez':file.replace(/\s*\.mp4$/i,'');return `<figure class="gallery-video-card"><div class="gallery-video-player"><video playsinline preload="none" poster="assets/videos/${encodeURIComponent(category)}/${encodeURIComponent(file.replace(/\.mp4$/i,'.jpg'))}" aria-label="${title}" src="assets/videos/${encodeURIComponent(category)}/${encodeURIComponent(file)}"></video><button class="gallery-video-play" type="button" aria-label="Redă: ${title}"><span aria-hidden="true">▶</span></button></div><figcaption>${title}</figcaption></figure>`}).join('')}</div>`}
const D=window.FDBS_DATA, main=document.querySelector('#main');
const norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const track=(event,params={})=>{if(localStorage.getItem('fdbs-consent')==='granted')window.gtag('event',event,params)};
const button=(label,href,ghost=false)=>`<a class="button${ghost?' ghost':''}" href="${href}">${label}</a>`;
const hero=(title,copy,eyebrow='Donează sânge',className='')=>`<section class="page-hero${className?` ${className}`:''}"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`;
const wrap=(html,alt=false)=>`<section class="section${alt?' alt':''}"><div class="container">${html}</div></section>`;

function home(){return `<section class="hero"><div class="hero-inner"><span class="eyebrow">Fundația Donatorilor Benevoli de Sânge</span><h1 class="display">Donează sânge.<br>Poți salva o viață.</h1><p>Un gest care durează câteva minute poate însemna o nouă șansă pentru cineva.</p><div class="actions">${button('Vreau să donez','#/pot-sa-donez')}${button('Găsește un centru','#/centre',true)}</div></div></section>
${wrap(`<div class="quick-check"><div><span class="eyebrow">Verificare rapidă</span><h2>Pot să donez?</h2><p>Acestea sunt câteva dintre criteriile generale. Medicul de la triaj ia decizia finală.</p>${button('Verifică dacă poți dona','#/pot-sa-donez')}</div><div class="criteria"><div class="criterion"><b>18–60 ani</b><span>interval general de vârstă</span></div><div class="criterion"><b>50–130 kg</b><span>interval de greutate</span></div><div class="criterion"><b>Stare bună</b><span>de sănătate</span></div><div class="criterion"><b>Act valabil</b><span>de identitate</span></div></div></div>`,true)}
${wrap(`<div class="section-head"><div><span class="eyebrow">Simplu, în cinci pași</span><h2>Donarea, pe scurt</h2></div><a class="text-link" href="#/cum-donez">Vezi cum se desfășoară →</a></div><div class="process">${['Pregătește-te','Mergi la centru','Treci prin triaj','Donează','Odihnește-te'].map((x,i)=>`<div><span>0${i+1}</span><h3>${x}</h3></div>`).join('')}</div>`)}
${wrap(`<div class="map-preview"><div><span class="eyebrow">47 de locații</span><h2>Găsește centrul cel mai apropiat</h2><p>Folosește căutarea după oraș sau județ și deschide traseul direct în Google Maps.</p>${button('Caută un centru','#/centre')}</div><div class="map-mini map" id="home-map"></div></div>`)}
${wrap(`<div class="section-head"><div><span class="eyebrow">Întrebări reale</span><h2>Ai o întrebare despre donare?</h2></div></div><div class="search-box" style="max-width:760px"><input id="home-faq-search" placeholder="Caută: medicamente, tatuaj, menstruație, stomatolog…"><a class="button" href="#/faq">Caută</a></div>`,true)}
${wrap(`<div class="section-head"><div><span class="eyebrow">Acum la FDBS</span><h2>Lucrăm pentru donatori</h2></div></div><div class="grid-3" style="grid-template-columns:1fr 1fr"><article class="project-card eligibility-project-card"><span class="eyebrow">Proiect în desfășurare</span><h3>Actualizarea criteriilor de eligibilitate</h3><p>Excluderea donatorilor trebuie să se bazeze pe riscuri medicale reale și dovezi actuale.</p><a class="text-link" href="#/criterii">Vezi proiectul →</a></article><article class="project-card donorium-card"><span class="eyebrow">Proiect fondat de FDBS</span><h3>Donorium</h3><p><b>Peste 240.000 de utilizatori</b><br>O comunitate digitală care face donarea mai simplă.</p><a class="text-link" href="#/donorium">Descoperă proiectul →</a></article></div>`)}
${wrap(`<div class="section-head"><div><span class="eyebrow">Din 1996</span><h2>Alături de donatori.</h2></div><p>FDBS lucrează pentru ca mai mulți oameni să doneze sânge și pentru ca experiența donatorilor din România să fie mai bună.</p></div>${button('Citește povestea FDBS','#/istoric')}`,true)}`}

function eligibility(){return hero('Pot să donez?','Verifică principalele criterii înainte de a merge la centru. Aceste informații te ajută să te orientezi; decizia finală aparține medicului de la triaj.')+wrap(`<div class="criteria"><div class="criterion"><b>18–60 ani</b><span>vârsta generală</span></div><div class="criterion"><b>50–130 kg</b><span>masă corporală acceptată</span></div><div class="criterion"><b>Fără alcool</b><span>în ultimele 48 de ore</span></div><div class="criterion"><b>Stare bună</b><span>de sănătate în ziua donării</span></div></div><div class="notice" style="margin-top:35px"><b>Ai o situație medicală specifică?</b><br>Caută în întrebările frecvente sau discută direct cu medicul de la triaj.</div><div class="actions">${button('Caută în întrebări','#/faq')}${button('Găsește un centru','#/centre',true)}</div>`)}
function how(){const steps=[['Cu 48 de ore înainte','Nu consuma alcool în cele 48 de ore înainte de donare.'],['Cu o zi înainte','Odihnește-te bine și bea suficiente lichide.'],['În dimineața donării','Nu veni nemâncat. Mănâncă ceva consistent, evită excesul de grăsimi și poartă haine care permit accesul ușor la braț.'],['Înregistrarea','Prezintă un act de identitate valabil și completează chestionarul donatorului.'],['Triajul','Răspunde sincer. Interviul medical și rezultatele analizelor sunt confidențiale.'],['Donarea','Se recoltează aproximativ 450 ml, în general în 7–10 minute, cu un kit steril de unică folosință.'],['După donare','Odihnește-te, hidratează-te și evită efortul fizic intens. Nu fuma o oră înainte și o oră după donare.']];return hero('Cum donez?','Donarea propriu-zisă durează doar câteva minute. Pregătește-te corect și acordă-ți puțin timp pentru refacere după.')+wrap(`<div class="steps">${steps.map((s,i)=>`<article class="step"><div class="step-number">${String(i+1).padStart(2,'0')}</div><div><h2>${s[0]}</h2><p>${s[1]}</p></div></article>`).join('')}</div><div class="notice"><b>Ți-e frică de ace sau știi că ai tendința să amețești?</b><br>Spune-i personalului medical. Este mai bine să știe de la început.</div><div class="actions">${button('Găsește un centru de donare','#/centre')}</div>`)}

function centresPage(){return hero('Unde pot dona?','Caută după oraș, județ sau denumirea centrului. Programul se poate modifica; verifică înainte de deplasare dacă ai dubii.','Donează sânge','centres-page-hero')+wrap(`<div class="directory-layout"><div class="directory-list"><div class="directory-controls"><div class="search-box"><input id="centre-search" aria-label="Caută centru" placeholder="Caută oraș sau județ…"><button class="button" id="locate">Locația mea</button></div><small id="centre-count">${D.centres.length} locații</small></div><div id="centre-results"></div></div><div class="map" id="centre-map" aria-label="Harta centrelor de transfuzie"></div></div>`)}
const centreHoursLabel=c=>c.hours?`${['CTS Prahova','CTS Vrancea','CRTS Galați'].includes(c.name)?'':`${c.days}, `}${c.hours}`:c.days;
const citySlug=city=>norm(city).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function centreCard(c,d=''){return `<article class="centre-card" data-id="${c.id}" tabindex="0" style="position:relative;padding-right:88px"><h3>${c.name}</h3><p>${c.city}${d?` · <b>${d} km</b>`:''}</p><p>${c.address}</p><p><b>${centreHoursLabel(c)}</b></p><a class="text-link centre-details" href="#/centre/${citySlug(c.city)}">Detalii centru →</a><a class="navigate" target="_blank" rel="noopener" aria-label="Navighează cu Google Maps" title="Navighează cu Google Maps" href="https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}" style="position:absolute;right:22px;top:50%;transform:translateY(-50%);display:block;width:48px;height:48px"><img src="assets/google-maps-icon.png" alt="" width="48" height="48" style="display:block;width:100%;height:100%;object-fit:contain"></a></article>`}
function cityCentrePage(slug){const centres=D.centres.filter(c=>citySlug(c.city)===slug),city=centres[0]?.city;if(!city)return hero('Centru negăsit','Revino la harta centrelor pentru a căuta o altă localitate.')+wrap(button('Vezi toate centrele','#/centre'));const plural=centres.length>1,map=city==='București'?`<section class="bucharest-map-section" aria-labelledby="bucharest-map-title"><span class="eyebrow">Cele 4 locații</span><h2 id="bucharest-map-title">Harta centrelor de donare din București</h2><p>Selectează un punct de colectă pentru a vedea adresa și orarul.</p><div class="bucharest-map" id="bucharest-map" aria-label="Harta Bucureștiului cu cele patru centre de donare"></div></section>`:'',centreNotes=centres.flatMap(c=>c.notes||[]),intro=centreNotes.length?centreNotes.join(' '):`${plural?`În ${city} sunt listate ${centres.length} centre unde poți dona sânge.`:`Aici găsești informațiile disponibile despre centrul de donare de sânge din ${city}.`} Programul se poate modifica; verifică înainte de deplasare dacă ai dubii.`;return `<nav class="breadcrumbs" aria-label="Navigare secundară"><a href="#/centre">Unde pot dona?</a><span aria-hidden="true">/</span><span>${city}</span></nav>${hero(`Donare de sânge în ${city}`,intro,'')}${wrap(`${map}<div class="city-centre-layout"><div><span class="eyebrow">${plural?'Centre în oraș':'Centrul din oraș'}</span><h2>${plural?`Unde poți dona în ${city}`:`Centrul de donare din ${city}`}</h2><div class="city-centre-list">${centres.map(c=>`<article class="city-centre-card" data-city-centre-id="${c.id}" tabindex="-1"><h3>${c.name}</h3><dl><div><dt>Adresă</dt><dd>${c.address}, ${c.city}</dd></div><div><dt>Program</dt><dd>${c.hours?centreHoursLabel(c):'Programul urmează să fie completat'}</dd></div></dl><a class="button small" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}">Deschide în Google Maps</a></article>`).join('')}</div></div><aside class="city-donation-help"><span class="eyebrow">Înainte să pleci</span><h2>Pregătește-te pentru donare</h2><p>Verifică informațiile esențiale despre eligibilitate și pașii donării.</p><a class="text-link" href="#/pot-sa-donez">Pot să donez? →</a><a class="text-link" href="#/cum-donez">Cum donez? →</a><a class="text-link" href="#/faq">Întrebări frecvente →</a></aside></div><div class="notice city-centre-notice"><b>Informațiile despre program se pot modifica.</b><br>Dacă ai dubii, verifică programul înainte de deplasare.</div><p class="back-to-directory"><a class="text-link" href="#/centre">← Vezi harta tuturor centrelor de donare</a></p>`)}`}
function initBucharestMap(){const map=document.getElementById('bucharest-map'),centres=D.centres.filter(c=>c.city==='București'),data=window.BUCHAREST_MAP_DATA;if(!map||!data)return;const [minLng,minLat,maxLng,maxLat]=data.bbox,point=({lng,lat})=>({x:(lng-minLng)/(maxLng-minLng)*100,y:(maxLat-lat)/(maxLat-minLat)*64}),roads=[['Splaiul Independenței',[[25.96,44.447],[26.03,44.440],[26.08,44.429],[26.14,44.410],[26.20,44.398]]],['Bd. Iuliu Maniu',[[25.96,44.434],[26.01,44.434],[26.06,44.435],[26.08,44.433]]],['Calea Victoriei',[[26.085,44.426],[26.088,44.442],[26.091,44.459]]],['Magheru–Brătianu',[[26.098,44.462],[26.101,44.446],[26.103,44.425]]],['Kiseleff–Aviatorilor',[[26.071,44.510],[26.080,44.480],[26.089,44.458]]],['Ștefan cel Mare–Mihai Bravu',[[26.097,44.458],[26.130,44.451],[26.140,44.421],[26.139,44.387]]],['Bd. Unirii',[[26.083,44.427],[26.115,44.426],[26.161,44.424]]],['Calea Plevnei',[[26.020,44.449],[26.060,44.443],[26.090,44.438]]]],roadPaths=roads.map(([name,coords])=>`<path class="city-road" d="M${coords.map(p=>{const q=point({lng:p[0],lat:p[1]});return `${q.x.toFixed(2)} ${q.y.toFixed(2)}`}).join(' L')}"><title>${name}</title></path>`).join(''),sectors=data.sectors.map(s=>`<path class="city-sector sector-${s.id}" d="${s.path}"><title>Sectorul ${s.id}</title></path>`).join(''),labels=[[1,26.035,44.49],[2,26.145,44.485],[3,26.175,44.43],[4,26.11,44.375],[5,26.025,44.39],[6,25.985,44.455]].map(([n,lng,lat])=>{const p=point({lng,lat});return `<text class="sector-label" x="${p.x}" y="${p.y}">S${n}</text>`}).join('');map.innerHTML=`<svg class="bucharest-map-lines" viewBox="0 0 100 64" preserveAspectRatio="none" role="img" aria-label="Conturul Bucureștiului, limitele sectoarelor și arterele principale">${sectors}${roadPaths}${labels}</svg>`;centres.forEach((c,i)=>{const p=point(c),m=document.createElement('button');m.className='bucharest-marker';m.style=`left:${p.x}%;top:${p.y/64*100}%`;m.dataset.cityCentreId=c.id;m.setAttribute('aria-label',`${c.name}, ${c.address}`);m.innerHTML=`<span>${i+1}</span>`;m.onclick=()=>{map.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));m.classList.add('active');const card=document.querySelector(`[data-city-centre-id="${c.id}"]`);card?.focus({preventScroll:true});card?.scrollIntoView({behavior:'smooth',block:'start'})};map.append(m)})}
const romaniaBoundary=[[22.710531,47.882194],[23.142236,48.096341],[23.760958,47.985598],[24.402056,47.981878],[24.866317,47.737526],[25.207743,47.891056],[25.945941,47.987149],[26.19745,48.220881],[26.619337,48.220726],[26.924176,48.123264],[27.233873,47.826771],[27.551166,47.405117],[28.12803,46.810476],[28.160018,46.371563],[28.054443,45.944586],[28.233554,45.488283],[28.679779,45.304031],[29.149725,45.464925],[29.603289,45.293308],[29.626543,45.035391],[29.141612,44.82021],[28.837858,44.913874],[28.558081,43.707462],[27.970107,43.812468],[27.2424,44.175986],[26.065159,43.943494],[25.569272,43.688445],[24.100679,43.741051],[23.332302,43.897011],[22.944832,43.823785],[22.65715,44.234923],[22.474008,44.409228],[22.705726,44.578003],[22.459022,44.702517],[22.145088,44.478422],[21.562023,44.768947],[21.483526,45.18117],[20.874313,45.416375],[20.762175,45.734573],[20.220192,46.127469],[21.021952,46.316088],[21.626515,46.994238],[22.099768,47.672439],[22.710531,47.882194]];
const mapPoint=([lng,lat])=>[(lng-20.5)/(29.8-20.5)*88+6,(48.3-lat)/(48.3-43.4)*78+10];
function mapRingPath(ring){return ring.map((point,i)=>`${i?'L':'M'}${mapPoint(point).map(n=>n.toFixed(2)).join(' ')}`).join(' ')+' Z'}
function countyMapPaths(){return (window.ROMANIA_COUNTIES||[]).map(county=>`<path class="county-shape" data-county="${county.name}" d="${county.polygons.map(polygon=>polygon.map(mapRingPath).join(' ')).join(' ')}"><title>${county.name}</title></path>`).join('')}
function renderMap(list,targetId='centre-map'){const map=document.getElementById(targetId);if(!map)return;const outline=romaniaBoundary.map((point,i)=>`${i?'L':'M'}${mapPoint(point).map(n=>n.toFixed(2)).join(' ')}`).join(' ')+' Z';const counties=countyMapPaths();map.innerHTML=`<svg class="country-outline" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Harta României cu limitele județelor">${counties||`<path class="country-fill" d="${outline}"/>`}</svg>`;const bucharest=list.filter(c=>c.city==='București'),locations=list.filter(c=>c.city!=='București');if(bucharest.length>1){const cluster={lng:bucharest.reduce((s,c)=>s+c.lng,0)/bucharest.length,lat:bucharest.reduce((s,c)=>s+c.lat,0)/bucharest.length};let [x,y]=mapPoint([cluster.lng,cluster.lat]),m=document.createElement('button');m.className='marker marker-cluster';m.style=`left:${x}%;top:${y}%`;m.textContent=bucharest.length;m.title=`${bucharest.length} centre de donare în București`;m.setAttribute('aria-label',m.title);m.onclick=()=>showCentreGroupPopover(bucharest,cluster,true);m.onmouseenter=()=>showCentreGroupPopover(bucharest,cluster,false);m.onmouseleave=()=>map.querySelector('.map-popover.hover')?.remove();m.onfocus=()=>showCentreGroupPopover(bucharest,cluster,false);m.onblur=()=>map.querySelector('.map-popover.hover')?.remove();map.append(m)}locations.forEach(c=>{let [x,y]=mapPoint([c.lng,c.lat]);let m=document.createElement('button');m.className='marker';m.style=`left:${x}%;top:${y}%`;m.dataset.id=c.id;m.title=`${c.name}, ${c.city}`;m.setAttribute('aria-label',m.title);m.onclick=()=>selectCentre(c.id);m.onmouseenter=()=>showCentrePopover(c,false);m.onmouseleave=()=>map.querySelector('.map-popover.hover')?.remove();m.onfocus=()=>showCentrePopover(c,false);m.onblur=()=>map.querySelector('.map-popover.hover')?.remove();map.append(m)})}
const centreAlphabeticalKey=centre=>centre.name.replace(/^CR?TS\s+/i,'').trim();
const centresBucharestFirst=centres=>[...centres].sort((a,b)=>{const bucharestOrder=(b.city==='București')-(a.city==='București');return bucharestOrder||centreAlphabeticalKey(a).localeCompare(centreAlphabeticalKey(b),'ro',{sensitivity:'base'})});
function scrollCentreCardToTop(card){const scroller=card?.closest('.directory-list');if(!scroller)return;const controls=scroller.querySelector('.directory-controls'),target=scroller.scrollTop+card.getBoundingClientRect().top-scroller.getBoundingClientRect().top-(controls?.offsetHeight||0);scroller.scrollTo({top:Math.max(0,target),behavior:'smooth'})}
function focusBucharestCentres(){sessionStorage.setItem('fdbs-focus-bucharest','1');if(currentRoutePath()!=='/centre'){navigateToRoute('/centre');return}const input=document.getElementById('centre-search');if(!input)return;sessionStorage.removeItem('fdbs-focus-bucharest');input.value='București';input.dispatchEvent(new Event('input'));requestAnimationFrame(()=>{const card=document.querySelector('.centre-card');card?.focus({preventScroll:true});scrollCentreCardToTop(card)})}
function initCentres(){let list=centresBucharestFirst(D.centres),results=document.getElementById('centre-results'),input=document.getElementById('centre-search');const draw=()=>{results.innerHTML=list.map(c=>centreCard(c,c.distance)).join('');document.getElementById('centre-count').textContent=`${list.length} ${list.length===1?'locație':'locații'}`;renderMap(list);bindCards()};const bindCards=()=>document.querySelectorAll('.centre-card').forEach(card=>{card.onclick=e=>{if(!e.target.closest('.navigate'))selectCentre(+card.dataset.id)};card.onkeydown=e=>{if(e.key==='Enter')selectCentre(+card.dataset.id)}});input.oninput=()=>{let q=norm(input.value);list=centresBucharestFirst(D.centres.filter(c=>norm(`${c.name} ${c.city} ${c.county}`).includes(q)));draw();track('centre_search',{search_term:input.value,result_count:list.length})};document.getElementById('locate').onclick=()=>navigator.geolocation?navigator.geolocation.getCurrentPosition(pos=>{const la=pos.coords.latitude,lo=pos.coords.longitude;list=D.centres.map(c=>({...c,distance:(111*Math.sqrt((c.lat-la)**2+((c.lng-lo)*Math.cos(la*Math.PI/180))**2)).toFixed(1)})).sort((a,b)=>a.distance-b.distance);draw();track('use_my_location')},()=>alert('Locația nu a putut fi accesată. Poți căuta în continuare după oraș sau județ.')):alert('Browserul nu oferă acces la locație.');draw();if(sessionStorage.getItem('fdbs-focus-bucharest'))focusBucharestCentres()}
function keepMapPopoverInside(map,p,rawX){const gap=12,half=p.offsetWidth/2,target=map.clientWidth*rawX/100,min=half+gap,max=map.clientWidth-half-gap;p.style.left=`${Math.max(min,Math.min(max,target))}px`}
function showCentrePopover(c,persistent=true){const map=document.getElementById('centre-map')||document.getElementById('home-map');if(!map)return;map.querySelectorAll('.map-popover').forEach(p=>p.remove());const [rawX,y]=mapPoint([c.lng,c.lat]);const p=document.createElement('div');p.className=`map-popover${persistent?'':' hover'}${y<31?' below':''}`;p.style.left=`${rawX}%`;p.style.top=`${y}%`;p.innerHTML=`<b>${c.name}</b><small>${c.address}, ${c.city}<br>${c.hours?centreHoursLabel(c):'Programul urmează să fie completat'}</small>${persistent?`<a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}">Navighează →</a>`:''}`;map.append(p);keepMapPopoverInside(map,p,rawX)}
function showCentreGroupPopover(centres,position,persistent=true){const map=document.getElementById('centre-map')||document.getElementById('home-map');if(!map)return;map.querySelectorAll('.map-popover').forEach(p=>p.remove());const [rawX,y]=mapPoint([position.lng,position.lat]),p=document.createElement('div');p.className=`map-popover map-popover-group${persistent?'':' hover'}${y<31?' below':''}`;p.style.left=`${rawX}%`;p.style.top=`${y}%`;p.innerHTML=`<b>${centres.length} centre în București</b><small>${centres.map(c=>c.name).join('<br>')}</small>${persistent?'<a class="text-link" href="#/centre" onclick="event.preventDefault();focusBucharestCentres()">Vezi centrele →</a>':''}`;map.append(p);keepMapPopoverInside(map,p,rawX)}
function selectCentre(id){const c=D.centres.find(x=>x.id===+id),map=document.getElementById('centre-map');if(!c||!map)return;document.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));document.querySelectorAll(`[data-id="${id}"]`).forEach(x=>x.classList.add('active'));scrollCentreCardToTop(document.querySelector(`.centre-card[data-id="${id}"]`));showCentrePopover(c,true);track('centre_marker_open',{centre:c.name,city:c.city})}

function faqPage(){let cats=[...new Set(D.faqs.map(f=>f.category))];return hero('Întrebări frecvente','Ai o întrebare despre donarea de sânge? Caută după cuvintele pe care le-ai folosi în mod obișnuit.')+wrap(`<div class="faq-tools"><div class="search-box"><input id="faq-search" placeholder="Caută: medicamente, tatuaj, cafea, analize…"></div><div class="filter-row"><button class="chip active" data-cat="">Toate</button>${cats.map(c=>`<button class="chip" data-cat="${c}">${c}</button>`).join('')}</div></div><div class="faq-list" id="faq-list"></div><div class="notice" style="margin-top:50px"><b>Nu ai găsit răspunsul?</b><br>Scrie-ne. Decizia finală privind acceptarea la donare aparține medicului de la centrul de transfuzie.</div>`)}
const legalSourceKey=source=>({'Legea 282/2005':'legea-282-2005','HG 1364/2006':'hg-1364-2006','Norme aplicare 282 (OMS 1193/2007)':'oms-1193-2007'}[source]||'');
function initFaq(){let q='',cat='',shown=15;const faqKey=x=>norm(x.question).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),draw=()=>{const list=document.getElementById('faq-list'),f=D.faqs.filter(x=>(!cat||x.category===cat)&&norm(`${x.question} ${x.answer} ${x.keywords}`).includes(norm(q))),visible=f.slice(0,shown);list.innerHTML=f.length?visible.map(x=>`<article class="faq-item" id="faq-${faqKey(x)}" data-faq-key="${faqKey(x)}"><button aria-expanded="false">${x.question}<span>＋</span></button><div class="faq-answer"><span class="eyebrow">${x.category}</span><p>${x.answer}</p>${x.related_page?`<a class="button ghost small" href="${x.related_page}">Vezi mai mult</a>`:''}${x.legal_source?`<a class="faq-legal-source" href="#/legislatie?act=${legalSourceKey(x.legal_source)}">${x.legal_source}</a>`:''}</div></article>`).join('')+(f.length>shown?`<div class="faq-more"><button class="button" type="button">Vezi mai multe</button><small>${f.length-shown} întrebări rămase</small></div>`:''):`<div class="notice"><b>Nu am găsit un răspuns.</b><br>Încearcă o formulare mai scurtă sau scrie-ne întrebarea.</div>`;list.querySelectorAll('.faq-item>button').forEach(b=>b.onclick=()=>{b.parentElement.classList.toggle('open');b.setAttribute('aria-expanded',b.parentElement.classList.contains('open'))});list.querySelectorAll('[data-faq-target]').forEach(link=>link.onclick=event=>{event.preventDefault();openFaq(link.dataset.faqTarget)});const more=list.querySelector('.faq-more button');if(more)more.onclick=()=>{shown+=15;draw()}},openFaq=key=>{const index=D.faqs.findIndex(x=>faqKey(x)===key);if(index<0)return;q='';cat='';shown=Math.max(15,index+1);document.getElementById('faq-search').value='';document.querySelectorAll('.chip').forEach(chip=>chip.classList.toggle('active',chip.dataset.cat===''));draw();const item=document.querySelector(`[data-faq-key="${key}"]`);item?.classList.add('open');item?.querySelector(':scope>button')?.setAttribute('aria-expanded','true');history.replaceState({},'',`${location.pathname}${location.search}#faq-${key}`);item?.scrollIntoView({behavior:'smooth',block:'center'})};document.getElementById('faq-search').oninput=e=>{q=e.target.value;shown=15;draw();track('faq_search',{search_term:q})};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelector('.chip.active')?.classList.remove('active');b.classList.add('active');cat=b.dataset.cat;shown=15;draw()});draw();const initial=location.hash.match(/^#faq-(.+)$/);if(initial)openFaq(initial[1])}

function projects(){return hero('Acum la FDBS','','')+wrap(`<div class="grid-3" style="grid-template-columns:1fr 1fr"><article class="project-card eligibility-project-card"><h3>Actualizare a criteriilor de eligibilitate a donatorilor în România</h3><p>Lucrăm pentru criterii bazate pe riscuri medicale reale și dovezi științifice actuale, urmărind sistemele occidentale de transfuzie.</p><a class="text-link" href="#/criterii">Vezi proiectul →</a></article><article class="project-card donorium-card"><h3>Donorium</h3><p>FDBS este unul dintre fondatorii platformei cu peste 240.000 de utilizatori.</p><a class="text-link" href="#/donorium">Descoperă proiectul →</a></article></div>`)}
function criteriaProject(){return hero('Actualizarea criteriilor de eligibilitate','Lucrăm pentru actualizarea criteriilor din România, astfel încât excluderea de la donare să se bazeze pe riscuri medicale reale și dovezi științifice actuale.','Acum la FDBS')+wrap(`<div class="steps"><article class="step criteria-analysis-step"><div class="step-number">2025</div><div><h2>Prezentarea analizei comparative</h2><p>Analiza criteriilor din România, Italia și Regatul Unit a fost prezentată la Congresul Național al Societății Române de Hematologie 2025.</p></div></article></div><div class="notice"><b>Analiză comparativă: România, Italia și Regatul Unit</b><br><a class="button" style="margin-top:16px" href="assets/analiza-comparativa-criterii-eligibilitate-ro-it-uk.pdf" download>Descarcă PDF</a></div>`)}
function donorium(){return hero('Donorium','Ne doream de la mijlocul anilor 2000 să folosim tehnologia pentru a ajuta donatorii cumva. Un site informativ a fost un prim pas, dar Donorium ne-a oferit ocazia să ajutăm centrele și donatorii mult mai mult.','Acum la FDBS')+`<figure class="donorium-hero"><img src="assets/lansare-donorium-fondatori-platforma-donare-sange-romania.jpg" alt="Echipa Donorium la evenimentul de lansare al platformei pentru donatorii de sânge."><figcaption>Echipa Donorium la evenimentul de lansare al platformei.</figcaption></figure><div class="donorium-story"><p>Platforma s-a lansat la 1 decembrie 2018 în 5 centre (București, Ploiești, Constanța, Bacău și Arad) și s-a extins ajungând la un maximum de 35 de centre în anul 2020.</p><p>Donatorii se pot programa în aplicație, pot parcurge un chestionar rapid de eligibilitate, pot să-și încarce donările în aplicație, pot lansa și răspunde la apeluri de donare și-și pot invita prietenii să devină donatori. Versiunea 2.0 a fost lansată în 2023 pentru telefoane Android, iOS și Huawei.</p></div>`+wrap(`<div class="map-preview"><div><span class="eyebrow">Peste</span><h2>240.000</h2><p>de utilizatori fac parte din comunitatea Donorium.</p><a class="button light" href="https://donorium.ro" target="_blank" rel="noopener">Vizitează Donorium</a></div><div><h2>O comunitate pentru donatori</h2><p>Donorium a fost creat pentru a face mai simplă legătura dintre donatori și centrele de transfuzie sanguină din România.</p></div></div>`)}
function galleryWallImages(){return Object.entries(window.FDBS_IMAGE_POOLS?.gallery||{}).flatMap(([period,value])=>{const images=Array.isArray(value)?value:value?[value]:[];return images.filter(image=>image.active!==false).map(image=>({...image,period}))})}
function galleryImageLabel(image){const key=(image.alt||'').trim().replace(/(tonitza)\d+$/,'$1'),labels={'conferinta de presa cts bucuresti':'Conferință de presă la CTS București','expozitie desene elevi tonitza':'Expoziția elevilor de la Liceul Tonitza','masa rotunda medici 2004':'Masă rotundă cu medici','carticica fotbal donare':'Fotbal și donare de sânge','carticica micii fotbalisti marii donatori':'Micii fotbaliști, marii donatori','prezentare liceu':'Prezentare pentru elevi','seminar profesori 2007':'Seminar pentru profesori','tabara donatori muntele rosu 2005':'Tabăra donatorilor, Muntele Roșu'};return labels[key]||key.replace(/[-_]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())||'Imagine din arhiva FDBS'}
function gallery(){const images=[...galleryWallImages(),...unartePhotoImages],periods=[...new Set(images.map(image=>image.period))].filter(period=>period!=='UNArte'),videoCategories=['UNArte','Logo Bigger','Donorium'];return `<section class="gallery-wall-hero"><div><span class="eyebrow">Arhiva fotografică FDBS</span><h1>Oameni, gesturi și momente.</h1></div><p>Imagini din istoria FDBS, campanii, întâlniri și proiecte dedicate donării benevole de sânge.</p></section><section class="gallery-wall-controls" aria-label="Filtre galerie"><div class="gallery-filter-groups"><div class="gallery-filter-group"><span class="gallery-filter-label">Foto</span><div class="gallery-wall-filters"><button class="gallery-filter active" data-gallery-period="toate">Toate</button>${periods.map(period=>`<button class="gallery-filter" data-gallery-period="${period}">${period}</button>`).join('')}<button class="gallery-filter" data-gallery-period="UNArte">UNArte</button></div></div><div class="gallery-filter-group"><span class="gallery-filter-label">Video</span><div class="gallery-wall-filters">${videoCategories.map(category=>`<button class="gallery-filter" data-gallery-video="${category}">${category}</button>`).join('')}</div></div></div><span class="gallery-wall-count">${images.length} fotografii</span></section><section class="gallery-video-panel notice" aria-live="polite" hidden><b></b><br><span>Videoclipurile din această categorie vor fi adăugate aici.</span></section><section class="gallery-photo-intro notice" hidden><p>Prin amabilitatea profesorului Iosif Oprescu, studenții de la <a href="https://unarte.org/">Universitatea Națională de Arte București</a> primesc în fiecare generație promovarea donării de sânge ca temă de exercițiu, prin video, postere, flyere și stickere. Unele dintre imaginile create de studenți sunt urcate aici, adesea cu logo-uri alternative create tot de ei.</p></section><section class="gallery-wall" aria-live="polite">${images.map((image,index)=>`<button class="gallery-wall-photo" data-period="${image.period}" data-no-title="${image.noTitle?'true':'false'}" data-src="${image.src}" data-label="${galleryImageLabel(image)}" aria-label="Mărește: ${galleryImageLabel(image)}"><img src="${image.src}" alt="${galleryImageLabel(image)}" loading="${index<8?'eager':'lazy'}">${image.noTitle?'':`<span class="gallery-wall-caption"><b>${galleryImageLabel(image)}</b><span>${image.period}</span></span>`}</button>`).join('')}</section><dialog class="gallery-viewer"><div><button class="gallery-viewer-close" type="button" aria-label="Închide">×</button><button class="gallery-viewer-nav gallery-viewer-prev" type="button" aria-label="Fotografia anterioară">‹</button><img alt=""><button class="gallery-viewer-nav gallery-viewer-next" type="button" aria-label="Fotografia următoare">›</button><p aria-live="polite"></p></div></dialog>`}
function initGalleryWall(){const wall=document.querySelector('.gallery-wall'),videoPanel=document.querySelector('.gallery-video-panel'),viewer=document.querySelector('.gallery-viewer'),count=document.querySelector('.gallery-wall-count');if(!wall||!videoPanel||!viewer)return;const photos=[...wall.querySelectorAll('.gallery-wall-photo')],previous=viewer.querySelector('.gallery-viewer-prev'),next=viewer.querySelector('.gallery-viewer-next');let activePhoto=null;const visiblePhotos=()=>photos.filter(photo=>!photo.hidden),showPhoto=photo=>{if(!photo)return;activePhoto=photo;const image=viewer.querySelector('img');image.src=photo.dataset.src;image.alt=photo.dataset.label;viewer.querySelector('p').innerHTML=`<b>${photo.dataset.label}</b><span>${photo.dataset.period}</span>`;viewer.querySelector('p').hidden=photo.dataset.noTitle==='true';const multiple=visiblePhotos().length>1;previous.hidden=!multiple;next.hidden=!multiple},move=direction=>{const visible=visiblePhotos(),index=visible.indexOf(activePhoto);if(index<0||visible.length<2)return;showPhoto(visible[(index+direction+visible.length)%visible.length])},activate=filter=>{document.querySelectorAll('.gallery-filter').forEach(button=>button.classList.remove('active'));filter.classList.add('active')};document.querySelectorAll('[data-gallery-period]').forEach(filter=>filter.onclick=()=>{activate(filter);wall.hidden=false;videoPanel.querySelectorAll('video').forEach(video=>video.pause());videoPanel.hidden=true;const period=filter.dataset.galleryPeriod;document.querySelector('.gallery-photo-intro').hidden=period!=='UNArte';let visible=0;photos.forEach(photo=>{const show=period==='toate'||photo.dataset.period===period;photo.hidden=!show;if(show)visible++});count.textContent=`${visible} fotografii`;if(viewer.open&&activePhoto?.hidden)viewer.close()});document.querySelectorAll('[data-gallery-video]').forEach(filter=>filter.onclick=()=>{activate(filter);document.querySelector('.gallery-photo-intro').hidden=true;wall.hidden=true;videoPanel.hidden=false;videoPanel.querySelectorAll('video').forEach(video=>video.pause());videoPanel.innerHTML=renderGalleryVideos(filter.dataset.galleryVideo);initGalleryVideoPlayers(videoPanel);count.textContent=galleryVideoFiles[filter.dataset.galleryVideo]?.length?`${galleryVideoFiles[filter.dataset.galleryVideo].length} ${galleryVideoFiles[filter.dataset.galleryVideo].length===1?'videoclip':'videoclipuri'} · ${filter.dataset.galleryVideo}`:`Video · ${filter.dataset.galleryVideo}`;if(viewer.open)viewer.close()});photos.forEach(photo=>photo.onclick=()=>{showPhoto(photo);viewer.showModal()});previous.onclick=()=>move(-1);next.onclick=()=>move(1);viewer.onkeydown=event=>{if(event.key==='ArrowLeft'){event.preventDefault();move(-1)}if(event.key==='ArrowRight'){event.preventDefault();move(1)}};viewer.querySelector('.gallery-viewer-close').onclick=()=>viewer.close();viewer.onclick=event=>{if(event.target===viewer)viewer.close()}}
function dailyGallery(){const day=Math.floor(Date.now()/86400000);return D.gallery.map((e,i)=>Object.assign([...e],{seed:(day*31+i*7)%12}))}
function galleryPoolKey(period){return period.replace('–','-').replace('2020-prezent','2020-prezent')}
function dailyGalleryImages(period,eraIndex){const pool=(window.FDBS_IMAGE_POOLS?.gallery?.[galleryPoolKey(period)]||[]).filter(image=>image.active!==false);if(!pool.length)return[];const day=Math.floor(Date.now()/86400000),start=(day+eraIndex*3)%pool.length;return Array.from({length:Math.min(3,pool.length)},(_,i)=>pool[(start+i)%pool.length])}
function applyDailyHomeHero(){const hero=document.querySelector('.hero'),pool=(D.homeHeroImages||[]).filter(image=>image.active!==false);if(!hero||!pool.length)return;const now=new Date(),dayKey=Number(`${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}`),image=pool[dayKey%pool.length];hero.style.setProperty('--hero-image',`url("${image.src}")`);hero.style.setProperty('--hero-position',image.position||'center');hero.style.setProperty('--hero-mobile-position',image.mobilePosition||image.position||'center');hero.setAttribute('role','img');hero.setAttribute('aria-label',image.alt||'Donare de sânge')}
function aboutPage(){return `<figure class="about-photo-hero"><img src="assets/despre-noi-voluntari-fdbs-fara-tevi.png" alt="Grup de voluntari FDBS la o campanie de donare de sânge"></figure>`+wrap(`<article class="about-story"><p class="about-lead">Fundația Donatorilor Benevoli de Sânge a început să prindă contur, informal, în 1996, iar din ianuarie 2001 funcționează oficial. Misiunea sa a rămas aceeași: să promoveze donarea benevolă și neremunerată de sânge și produse sanguine, să contribuie la informarea corectă a donatorilor și să le reprezinte interesele în dialogul cu Sistemul de Transfuzie și cu Ministerul Sănătății.</p>
<section><h2>De ce susținem donarea benevolă și neremunerată?</h2><p>În contextul donării de sânge, „benevol” înseamnă o decizie luată liber, fără obligații și fără presiuni — fie că acestea vin din partea unui superior, într-o structură militară, fie din dorința de a răspunde unei solicitări pentru o rudă, un prieten sau un pacient cunoscut.</p><p>Donarea benevolă contribuie la siguranța întregului sistem. O persoană care vine din proprie inițiativă poate răspunde mai deschis și mai sincer la întrebările din chestionarul de predonare, iar acest lucru ajută la protejarea atât a donatorului, cât și a pacientului.</p><p>La fel de important este principiul donării neremunerate.</p></section>
<section><h2>Un principiu pe care îl considerăm esențial</h2><p>În ultimii 30 de ani, sistemul de transfuzie din România a făcut progrese importante, dar a cunoscut și decizii pe care le considerăm regretabile. Una dintre ele este creșterea, începând cu 1 ianuarie 2024, a valorii beneficiului acordat după donare la 280 de lei. Din perspectiva noastră, această măsură intră în contradicție cu unul dintre principiile fundamentale prevăzute de lege:</p><blockquote><span>„Donarea de sânge este un act voluntar, anonim și neremunerat.”</span><cite><a href="#/legislatie?act=legea-282-2005">Legea nr. 282/2005</a></cite></blockquote><p>Schimbarea a adus mai mulți oameni în centrele de transfuzie, însă a accentuat și dificultăți deja existente. În <a class="about-inline-link" href="assets/documente/memoriu-ms-remunerare-donare.pdf" target="_blank">memoriul</a> adresat Ministerului Sănătății înainte de adoptarea măsurii, am arătat că aceleași resurse financiare ar fi putut fi investite în triplarea personalului și în dezvoltarea colectelor mobile — inclusiv prin achiziționarea anuală a trei autospeciale pentru transportul sângelui.</p><p>O asemenea investiție ar fi redus aglomerația și ar fi făcut donarea mai accesibilă în întreaga țară. În schimb, multe centre sunt astăzi și mai solicitate, iar relația de încredere dintre personal și donatori are de suferit. În multe dintre centre, de exemplu, persoanelor de peste 50 de ani li se cere să obțină de la medicul de familie o adeverință care să ateste că nu suferă de afecțiuni cronice, ceea ce presupune un drum în plus și poate descuraja donarea.</p></section>
<section><h2>Experiență împărtășită, soluții adaptate României</h2><p>Din 2001, reprezentăm România în <a class="about-inline-link" href="https://www.fiods-ifbdo.org/" target="_blank" rel="noopener">Federația Internațională a Organizațiilor Donatorilor de Sânge</a>. Această colaborare ne-a oferit ocazia de a învăța atât de la specialiști din țările occidentale, cât și de la voluntari și organizații din Asia, descoperind perspective și soluții pe care am încercat să le adaptăm realităților din România.</p><p>De-a lungul anilor, am susținut schimbări menite să facă experiența donării mai simplă și mai firească. Printre acestea s-au numărat eliminarea obligației ca donatorii din București să vină de două ori la centru dacă trecuseră mai mult de șase luni de la ultima donare, reducerea pragurilor de greutate — care, la începutul anilor 2000, erau de 60 de kilograme pentru bărbați și 58 pentru femei, printre cele mai ridicate din lume — și introducerea programărilor, pentru a diminua timpul petrecut la coadă.</p></section>
<section><h2>Schimbările durabile se construiesc împreună</h2><p>Ne-a încurajat să vedem că tot mai multe organizații au început să contribuie la îmbunătățirea sistemului, prin donații și achiziții pentru centrele de transfuzie sau prin proiecte desfășurate în mediul neguvernamental, mai ales după incendiul de la Colectiv. Am căutat să colaborăm cu toate aceste organizații și credem în continuare că schimbările durabile se construiesc împreună.</p><p>Activitatea noastră a luat forme dintre cele mai diverse: cursuri de comunicare pentru personalul centrelor de transfuzie, programe pentru medici privind utilizarea responsabilă a produselor sanguine, activități educative pentru preșcolari, elevi și studenți, concerte, expoziții, ghiduri și o aplicație dedicată donatorilor.</p></section>
<footer class="about-closing"><p>După 30 de ani, știm că progresul nu este nici simplu, nici liniar. Am avut reușite, am întâmpinat obstacole și am învățat din ambele. Vom continua să lucrăm pentru un sistem mai sigur, mai accesibil și mai atent la nevoile pacienților și ale donatorilor.</p></footer></article>`)}
function involve(){return hero('Implică-te','Poți ajuta printr-o colectă organizată cu centrul local, prin voluntariat sau prin sprijin financiar.')+wrap(`<div class="grid-3"><article class="card"><span class="num">01</span><h3>Organizează o donare</h3><p>Discută cu centrul de transfuzie din orașul tău despre o colectă pentru organizația sau comunitatea ta.</p><a class="text-link" href="#/implica-te/organizeaza-o-donare">Vezi cum începi →</a></article><article class="card"><span class="num">02</span><h3>Devino voluntar</h3><p>Implică-te în activitatea și campaniile FDBS.</p><a class="text-link" href="#/implica-te/devino-voluntar">Află cum te poți implica →</a></article><article class="card"><span class="num">03</span><h3>Sprijină-ne financiar</h3><p>Prin 3,5%, sponsorizare sau donație directă.</p><a class="text-link" href="#/implica-te/sprijina-ne-financiar">Vezi modalitățile →</a></article></div>`)}
function organizeDonation(){return hero('Organizează o donare','Transformă inițiativa colegilor, prietenilor sau comunității tale într-o acțiune organizată împreună cu centrul local de transfuzie.','Implică-te')+wrap(`<div class="steps"><article class="step"><div class="step-number">01</div><div><h2>Strânge o comunitate</h2><p>Discută cu oamenii interesați și estimează câți donatori pot participa. Centrul de transfuzie va confirma numărul minim și condițiile necesare pentru organizarea colectei.</p></div></article><article class="step"><div class="step-number">02</div><div><h2>Contactează centrul local</h2><p>Stabiliți împreună data, intervalul orar, locul și forma potrivită: colectă mobilă sau participare organizată la centru.</p></div></article><article class="step"><div class="step-number">03</div><div><h2>Pregătește logistica</h2><p>Asigură accesul echipei medicale, spațiul cerut de centru și o persoană de contact pentru coordonarea participanților.</p></div></article><article class="step"><div class="step-number">04</div><div><h2>Informează donatorii</h2><p>Trimite din timp informațiile despre eligibilitate, pregătire, actul de identitate și programul stabilit.</p></div></article></div><div class="notice"><b>Condițiile diferă de la un centru la altul.</b><br>Centrul de transfuzie decide dacă poate organiza colecta și confirmă cerințele medicale și logistice.</div><div class="actions">${button('Găsește centrul local','#/centre')}${button('Contactează FDBS','#/contact',true)}</div>`)}
function becomeVolunteer(){return hero('Devino voluntar','Contribuie cu timpul, experiența și energia ta la proiectele și campaniile FDBS.','Implică-te')+wrap(`<div class="grid-3"><article class="card"><span class="num">01</span><h3>Informarea donatorilor</h3><p>Ajută-ne să explicăm clar pregătirea pentru donare, criteriile de eligibilitate și pașii din centru.</p></article><article class="card"><span class="num">02</span><h3>Campanii și evenimente</h3><p>Poți sprijini organizarea, comunicarea și relația cu participanții la activitățile FDBS.</p></article><article class="card"><span class="num">03</span><h3>Competențe profesionale</h3><p>Spune-ne dacă ne poți ajuta prin comunicare, design, fotografie, educație, tehnologie sau alte competențe utile.</p></article></div><div class="notice" style="margin-top:35px"><b>Spune-ne cum ai vrea să contribui.</b><br>Scrie-ne câteva rânduri despre tine, disponibilitatea ta și tipul de activitate care te interesează.</div><div class="actions">${button('Scrie-ne','#/contact')}</div>`)}
function supportFinancially(){return hero('Sprijină-ne financiar','Ajută FDBS să continue proiectele de informare, reprezentare și sprijin pentru donatorii de sânge.','Implică-te')+wrap(`<div class="grid-3"><article class="card"><span class="num">01</span><h3>Redirecționează 3,5%</h3><p>Poți redirecționa o parte din impozitul pe venit către activitatea FDBS, fără un cost suplimentar pentru tine.</p></article><article class="card"><span class="num">02</span><h3>Sponsorizare</h3><p>Companiile pot susține proiectele FDBS printr-un contract de sponsorizare.</p></article><article class="card"><span class="num">03</span><h3>Donație directă</h3><p>Poți contribui direct la activitatea fundației. Contactează-ne pentru informațiile actuale și documentele necesare.</p></article></div><div class="notice" style="margin-top:35px"><b>Datele și documentele trebuie să fie actuale.</b><br>Scrie-ne pentru formularul, contractul sau informațiile de plată potrivite modalității alese.</div><div class="actions">${button('Solicită informațiile','#/contact')}</div>`)}
function legislation(){const documents=[
  {key:'legea-282-2005',type:'Lege',title:'Legea nr. 282 din 5 octombrie 2005',description:'Privind organizarea activității de transfuzie sanguină, donarea de sânge și componente sanguine de origine umană, precum și asigurarea calității și securității sanitare în vederea utilizării lor terapeutice.',url:'https://legislatie.just.ro/Public/DetaliiDocumentAfis/31711'},
  {key:'hg-1364-2006',type:'Hotărâre a Guvernului',title:'Hotărârea nr. 1364 din 4 octombrie 2006',description:'Pentru aprobarea drepturilor și obligațiilor donatorilor de sânge.',url:'https://legislatie.just.ro/Public/DetaliiDocument/75645'},
  {key:'oms-1193-2007',type:'Normă actualizată',title:'Normele din 7 iulie 2007 pentru aplicarea Legii nr. 282 din 5 octombrie 2005',description:'Privind admisibilitatea donatorilor de sânge și de componente sanguine umane.',url:'https://legislatie.just.ro/Public/DetaliiDocumentAfis/167170'}
];return hero('Legislație','Acte normative relevante pentru donarea de sânge și activitatea de transfuzie sanguină din România.','Info')+wrap(`<div class="legislation-list">${documents.map(document=>`<article class="legislation-card" id="act-${document.key}" data-legal-act="${document.key}" tabindex="-1"><span class="eyebrow">${document.type}</span><h2>${document.title}</h2><p>${document.description}</p><a class="button small" href="${document.url}" target="_blank" rel="noopener">Deschide documentul oficial ↗</a></article>`).join('')}</div><p class="legislation-source">Documentele se deschid pe Portalul Legislativ, sursa oficială administrată de Ministerul Justiției.</p>`)}
