function donorGuide(){return hero('Ghidul Donatorului','Informațiile esențiale care te ajută să te pregătești și să înțelegi pașii donării de sânge.','Info')+wrap(`<section class="donor-guide-document" aria-labelledby="donor-guide-document-title"><div class="donor-guide-document-head"><div><span class="eyebrow">Document pentru donatori</span><h2 id="donor-guide-document-title">Ghidul Donatorului</h2><p>Ghidul Donatorului a fost creat în 2016, dar marea majoritate a conținutului este actual și astăzi</p></div><a class="button" href="assets/documente/ghidul-donatorului-de-sange.pdf" download>Descarcă ghidul</a></div><iframe class="donor-guide-document-frame" src="assets/documente/ghidul-donatorului-de-sange.pdf" title="Previzualizare Ghidul Donatorului" loading="lazy"></iframe></section><div class="donor-guide-grid"><article class="project-card"><h3>Pot să donez?</h3><p>Verifică principalele criterii înainte să mergi la centrul de transfuzie.</p><a class="text-link" href="#/pot-sa-donez">Verifică eligibilitatea →</a></article><article class="project-card"><h3>Cum donez?</h3><p>Vezi cum te pregătești și care sunt etapele unei donări.</p><a class="text-link" href="#/cum-donez">Vezi pașii donării →</a></article><article class="project-card"><h3>Unde pot dona?</h3><p>Găsește centrul de transfuzie sau punctul de colectă potrivit.</p><a class="text-link" href="#/centre">Caută un centru →</a></article><article class="project-card"><h3>Întrebări frecvente</h3><p>Caută răspunsuri despre pregătire, eligibilitate și donare.</p><a class="text-link" href="#/faq">Caută un răspuns →</a></article></div>`)}
