function initContact(){const form=document.getElementById('contact-form'),reveal=document.getElementById('reveal-phones'),phones=document.getElementById('phone-list'),question=document.getElementById('captcha-question'),answer=document.getElementById('contact-captcha-answer'),submit=document.getElementById('contact-submit'),status=document.getElementById('contact-status');const setStatus=(message,type='')=>{status.textContent=message;status.className=`contact-status ${type}`.trim()};const loadCaptcha=async()=>{submit.disabled=true;submit.textContent='Se pregătește…';answer.value='';try{const response=await fetch('contact/send.php?action=captcha',{headers:{Accept:'application/json'},credentials:'same-origin'});if(!response.ok)throw new Error('captcha_failed');const data=await response.json();question.textContent=data.question;submit.disabled=false;submit.textContent='Trimite mesajul'}catch(error){question.textContent='indisponibil';setStatus('Formularul nu este disponibil momentan. Ne poți scrie direct la contact@doneazasange.ro.','error')}};loadCaptcha();if(form)form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;submit.disabled=true;submit.textContent='Se trimite…';setStatus('');try{const response=await fetch('contact/send.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'same-origin',body:JSON.stringify({name:form.elements.name.value.trim(),email:form.elements.email.value.trim(),subject:form.elements.subject.value.trim(),message:form.elements.message.value.trim(),captcha:form.elements.captcha_answer.value.trim(),website:form.elements.website.value})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Mesajul nu a putut fi trimis.');form.reset();setStatus('Mesajul a fost trimis. Îți mulțumim!','success');await loadCaptcha()}catch(error){setStatus(error.message||'Mesajul nu a putut fi trimis. Te rugăm să încerci din nou.','error');await loadCaptcha()}};if(reveal&&phones)reveal.onclick=()=>{const willShow=phones.hidden;phones.hidden=!willShow;reveal.setAttribute('aria-expanded',String(willShow));reveal.textContent=willShow?'Ascunde numerele de contact':'Arată numerele de contact';if(willShow)phones.querySelector('a')?.focus()}}
function privacy(){return hero('Confidențialitate și cookies','Colectăm doar datele necesare funcționării site-ului. Analiza anonimă a utilizării este activată numai cu acordul tău.')+wrap(`<h2>Preferințele tale</h2><p>Poți modifica oricând alegerea folosind „Preferințe cookies” din subsol. Căutările FAQ fără rezultat și interacțiunile cu centrele sunt trimise către instrumentul de analiză numai după consimțământ și nu includ date medicale ori coordonatele exacte ale utilizatorului.</p>`)}

const routes={'/':home,'/pot-sa-donez':eligibility,'/cum-donez':how,'/centre':centresPage,'/faq':faqPage,'/ghidul-donatorului':donorGuide,'/legislatie':legislation,'/articole':articles,'/acum':projects,'/criterii':criteriaProject,'/donorium':donorium,'/galerie':gallery,'/istoric':aboutPage,'/implica-te':involve,'/implica-te/organizeaza-o-donare':organizeDonation,'/implica-te/devino-voluntar':becomeVolunteer,'/implica-te/sprijina-ne-financiar':supportFinancially,'/contact':contactPage,'/confidentialitate':privacy};
const publicRoutes={'/':'/','/pot-sa-donez':'/pot-sa-donez/','/cum-donez':'/cum-donez/','/centre':'/centre/','/faq':'/intrebari-frecvente/','/ghidul-donatorului':'/ghidul-donatorului/','/legislatie':'/legislatie/','/articole':'/articole/','/acum':'/proiecte-actuale/','/criterii':'/criterii-eligibilitate/','/donorium':'/donorium/','/galerie':'/galerie/','/istoric':'/despre-noi/','/implica-te':'/implica-te/','/implica-te/organizeaza-o-donare':'/implica-te/organizeaza-o-donare/','/implica-te/devino-voluntar':'/implica-te/devino-voluntar/','/implica-te/sprijina-ne-financiar':'/implica-te/sprijina-ne-financiar/','/contact':'/contact/','/confidentialitate':'/confidentialitate/'};
const siteBasePath=location.protocol==='file:'?'':new URL('.',document.baseURI).pathname.replace(/\/$/,'');
function assetUrl(path){const clean=path.replace(/^\/+/,''),prefix=location.protocol==='file:'?(window.FDBS_ROOT_PREFIX||''):`${siteBasePath}/`;return `${prefix}${clean}`}
function publicRoutePath(path){const city=path.match(/^\/centre\/([^/]+)$/);return city?`/centre/${city[1]}/`:publicRoutes[path]||'/'}
function routeUrl(path){const url=publicRoutePath(path);return location.protocol==='file:'?`${window.FDBS_ROOT_PREFIX||''}index.html#${path}`:`${siteBasePath}${url}`}
function routeFromPublicPath(pathname){const clean=decodeURI(pathname).replace(/\/index\.html$/,'/').replace(/\/+$/,'/')||'/';const city=clean.match(/\/centre\/([^/]+)\/$/);if(city)return `/centre/${city[1]}`;const entry=Object.entries(publicRoutes).find(([,url])=>url==='/'?clean==='/':clean.endsWith(url));return entry?.[0]||'/'}
function currentRoutePath(){return location.hash.startsWith('#/')?location.hash.slice(1).split('?')[0]:routeFromPublicPath(location.pathname)}
function navigateToRoute(path){const url=routeUrl(path);if(location.protocol==='file:'){location.href=url;return}window.history.pushState({},'',url);route()}
function rewriteInternalLinks(root=document){root.querySelectorAll('a[href^="#/"]').forEach(a=>{const raw=a.getAttribute('href').slice(1),[path,query]=raw.split('?');a.href=routeUrl(path)+(query?`?${query}`:'')});if(siteBasePath)root.querySelectorAll('a[href^="/"]').forEach(a=>{const href=a.getAttribute('href');if(!href.startsWith(`${siteBasePath}/`))a.href=`${siteBasePath}${href}`})}
function updateCanonical(path){let canonical=document.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.append(canonical)}canonical.href=`https://doneazasange.ro${publicRoutePath(path)}`}
function route(){let path=currentRoutePath(),query=location.hash.startsWith('#/')?(location.hash.split('?')[1]||''):location.search.slice(1),cityMatch=path.match(/^\/centre\/([^/]+)$/),fn=cityMatch?()=>cityCentrePage(cityMatch[1]):routes[path]||home;if(location.protocol!=='file:'&&location.hash.startsWith('#/'))window.history.replaceState({},'',routeUrl(path)+(query?`?${query}`:''));main.innerHTML=fn();document.querySelector('#footer-cta').hidden=path==='/centre';window.scrollTo(0,0);document.title=`${path==='/'?'FDBS — Donează sânge':main.querySelector('h1')?.textContent+' — FDBS'}`;updateCanonical(path);rewriteInternalLinks(document);document.querySelector('.site-header').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');if(path==='/centre')initCentres();if(cityMatch?.[1]==='bucuresti')initBucharestMap();if(path==='/faq')initFaq();if(path==='/legislatie')initLegislation();if(path==='/galerie')initGalleryWall();if(path==='/contact')initContact();if(path==='/'){applyDailyHomeHero();renderMap(D.centres,'home-map');const input=document.getElementById('home-faq-search');input.onkeydown=e=>{if(e.key==='Enter')location.href=`${routeUrl('/faq')}?q=${encodeURIComponent(input.value)}`}}rewriteInternalLinks(main);track('page_view',{page_path:path})}
function initBucharestMap(){const map=document.getElementById('bucharest-map'),centres=D.centres.filter(c=>c.city==='București'),data=window.BUCHAREST_MAP_DATA;if(!map||!data)return;const [minLng,minLat,maxLng,maxLat]=data.bbox,point=({lng,lat})=>({x:4+(lng-minLng)/(maxLng-minLng)*92,y:15+(maxLat-lat)/(maxLat-minLat)*70}),sectors=data.sectors.map(s=>`<path class="city-sector sector-${s.id}" d="${s.path}"><title>Sectorul ${s.id}</title></path>`).join(''),labels=[[1,26.035,44.49],[2,26.145,44.485],[3,26.175,44.43],[4,26.11,44.375],[5,26.025,44.39],[6,25.985,44.455]].map(([n,lng,lat])=>{const x=(lng-minLng)/(maxLng-minLng)*100,y=(maxLat-lat)/(maxLat-minLat)*64;return `<text class="sector-label" x="${x}" y="${y}">S${n}</text>`}).join('');map.innerHTML=`<img class="bucharest-map-image" src="${assetUrl('assets/harta-bucuresti-detaliata.png')}" alt="Hartă detaliată a Bucureștiului cu străzi, spații verzi și lacuri"><svg class="bucharest-sector-overlay" viewBox="0 0 100 64" preserveAspectRatio="none" aria-label="Limitele celor șase sectoare ale Bucureștiului">${sectors}${labels}</svg>`;centres.forEach((c,i)=>{const p=point(c),m=document.createElement('button');m.className='bucharest-marker';m.style=`left:${p.x}%;top:${p.y}%`;m.dataset.cityCentreId=c.id;m.setAttribute('aria-label',`${c.name}, ${c.address}`);m.innerHTML=`<span>${i+1}</span>`;m.onclick=()=>{map.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));m.classList.add('active');const card=document.querySelector(`[data-city-centre-id="${c.id}"]`);card?.focus({preventScroll:true});card?.scrollIntoView({behavior:'smooth',block:'start'})};map.append(m)})}
const initBucharestMapBase=initBucharestMap;initBucharestMap=function(){initBucharestMapBase();const map=document.getElementById('bucharest-map'),zoom=1.42;if(!map)return;map.querySelector('.bucharest-map-image')?.classList.add('bucharest-map-zoom');map.querySelector('.bucharest-sector-overlay')?.classList.add('bucharest-map-zoom');map.querySelectorAll('.bucharest-marker').forEach(marker=>{marker.style.left=`${50+(parseFloat(marker.style.left)-50)*zoom}%`;marker.style.top=`${50+(parseFloat(marker.style.top)-50)*zoom}%`});map.querySelectorAll('.sector-label').forEach(label=>{const x=parseFloat(label.getAttribute('x')),y=parseFloat(label.getAttribute('y'));label.setAttribute('x',50+(x-50)*.7);label.setAttribute('y',32+(y-32)*.7)})};
const initBucharestMapWithZoom=initBucharestMap;initBucharestMap=function(){initBucharestMapWithZoom();const centres=D.centres.filter(c=>c.city==='București');document.querySelectorAll('.bucharest-marker').forEach((marker,i)=>{marker.dataset.name=centres[i]?.name||'';marker.title=centres[i]?.name||''})};
function showBucharestCentrePopover(c,marker){const map=document.getElementById('bucharest-map');if(!map)return;map.querySelectorAll('.map-popover').forEach(p=>p.remove());const top=parseFloat(marker.style.top),p=document.createElement('div');p.className=`map-popover hover${top<31?' below':''}`;p.style.left=marker.style.left;p.style.top=marker.style.top;p.innerHTML=`<b>${c.name}</b><small>${c.address}, ${c.city}<br>${c.hours?centreHoursLabel(c):'Programul urmează să fie completat'}</small>`;map.append(p)}
const initBucharestMapWithNames=initBucharestMap;initBucharestMap=function(){initBucharestMapWithNames();const map=document.getElementById('bucharest-map'),centres=D.centres.filter(c=>c.city==='București');map?.querySelectorAll('.bucharest-marker').forEach((marker,i)=>{const c=centres[i];marker.onmouseenter=()=>showBucharestCentrePopover(c,marker);marker.onmouseleave=()=>map.querySelector('.map-popover.hover')?.remove();marker.onfocus=()=>showBucharestCentrePopover(c,marker);marker.onblur=()=>map.querySelector('.map-popover.hover')?.remove()})};
