const cityCentrePageWithRedundantHeading=cityCentrePage;
function addCityScheduleVerification(slug){let html=cityCentrePageWithRedundantHeading(slug).replace(/<span class="eyebrow">(?:Centre|Centrul|Puncte|Punctul)[^<]*<\/span><h2>[^<]*<\/h2>(?=<div class="city-centre-list">)/,'');D.centres.filter(c=>citySlug(c.city)===slug&&c.hours&&!c.hours.includes('?')).forEach(c=>{const row=`<div><dt>Program</dt><dd>${centreHoursLabel(c)}</dd></div>`,booking=c.name==='Spitalul Clinic „Prof. Dr. D. Gerota”'?'<div class="centre-contact-note"><dd>Se pot face programări telefonic la 021.303.7080, int 28180.</dd></div>':'',verification=c.name==='CTS Hunedoara'?'<div class="schedule-verification"><dd>Informația despre program a fost verificată ultima dată pe <time datetime="2025-09-03">3 septembrie 2025</time>.</dd></div>':'<div class="schedule-verification"><dd>Program verificat la <time datetime="2026-08-18">18 august 2026</time></dd></div>';html=html.replace(row,`${row}${booking}${verification}`)});return html.replace('<b>Informațiile despre program se pot modifica.</b><br>Dacă ai dubii, verifică programul înainte de deplasare.','<b>Informațiile despre program se pot modifica.</b><br>Toate centrele din țară sunt închise în zilele de sărbătoare națională.<br>Dacă ai dubii, verifică programul înainte de deplasare.')}
cityCentrePage=addCityScheduleVerification;
